import nodemailer from 'nodemailer'

function createTransporter() {
  return nodemailer.createTransport({
    host: process.env.SMTP_HOST,
    port: Number(process.env.SMTP_PORT),
    secure: false,
    auth: {
      user: process.env.SMTP_USER,
      pass: process.env.SMTP_PASS,
    },
  })
}

async function send({ to, subject, html }) {
  const transporter = createTransporter()
  await transporter.sendMail({
    from: `"${process.env.FROM_NAME}" <${process.env.FROM_EMAIL}>`,
    to,
    subject,
    html,
  })
}

export async function sendApplicationConfirmation({ candidateEmail, candidateName, jobTitle, companyName }) {
  await send({
    to: candidateEmail,
    subject: `Application received — ${jobTitle} at ${companyName}`,
    html: `
      <div style="font-family:sans-serif;max-width:600px;margin:0 auto">
        <h2 style="color:#1a56db">Application Received</h2>
        <p>Hi ${candidateName},</p>
        <p>We've received your application for <strong>${jobTitle}</strong> at <strong>${companyName}</strong>.</p>
        <p>The employer will review your application and get back to you. You can track your application status in your dashboard.</p>
        <a href="${process.env.CLIENT_URL}/candidate/applications"
           style="display:inline-block;margin-top:16px;padding:12px 24px;background:#1a56db;color:#fff;text-decoration:none;border-radius:8px">
          View My Applications
        </a>
        <p style="margin-top:24px;color:#6b7280;font-size:14px">JobBoard — connecting talent with opportunity</p>
      </div>
    `,
  })
}

export async function sendNewApplicationAlert({ employerEmail, employerName, candidateName, jobTitle, applicationId }) {
  await send({
    to: employerEmail,
    subject: `New application for ${jobTitle}`,
    html: `
      <div style="font-family:sans-serif;max-width:600px;margin:0 auto">
        <h2 style="color:#1a56db">New Application</h2>
        <p>Hi ${employerName},</p>
        <p><strong>${candidateName}</strong> has applied for <strong>${jobTitle}</strong>.</p>
        <a href="${process.env.CLIENT_URL}/employer/applications/${applicationId}"
           style="display:inline-block;margin-top:16px;padding:12px 24px;background:#1a56db;color:#fff;text-decoration:none;border-radius:8px">
          Review Application
        </a>
        <p style="margin-top:24px;color:#6b7280;font-size:14px">JobBoard — connecting talent with opportunity</p>
      </div>
    `,
  })
}

export async function sendStatusUpdate({ candidateEmail, candidateName, jobTitle, status }) {
  const statusLabels = {
    reviewing: 'is being reviewed',
    shortlisted: 'has been shortlisted',
    rejected: 'was not selected',
    hired: 'has been accepted',
  }
  const label = statusLabels[status] ?? `status changed to ${status}`

  await send({
    to: candidateEmail,
    subject: `Application update — ${jobTitle}`,
    html: `
      <div style="font-family:sans-serif;max-width:600px;margin:0 auto">
        <h2 style="color:#1a56db">Application Update</h2>
        <p>Hi ${candidateName},</p>
        <p>Your application for <strong>${jobTitle}</strong> ${label}.</p>
