import { Router } from 'express'
import { body, validationResult } from 'express-validator'
import Job from '../models/Job.js'
import { protect, requireRole } from '../middleware/auth.js'

const router = Router()

const validate = (req, res, next) => {
  const errors = validationResult(req)
  if (!errors.isEmpty()) return res.status(400).json({ errors: errors.array() })
  next()
}

// GET /api/jobs — public search + list
router.get('/', async (req, res) => {
  try {
    const {
      q, location, type, category, experienceLevel, remote,
      salaryMin, salaryMax, page = 1, limit = 10, sort = 'newest',
    } = req.query

    const filter = { status: 'active' }

    if (q) filter.$text = { $search: q }
    if (location) filter.location = { $regex: location, $options: 'i' }
    if (type) filter.type = type
    if (category) filter.category = category
    if (experienceLevel) filter.experienceLevel = experienceLevel
    if (remote === 'true') filter.remote = true
    if (salaryMin) filter.salaryMin = { $gte: Number(salaryMin) }
    if (salaryMax) filter.salaryMax = { $lte: Number(salaryMax) }

    const sortMap = {
      newest: { createdAt: -1 },
      oldest: { createdAt: 1 },
      featured: { featured: -1, createdAt: -1 },
    }

    const skip = (Number(page) - 1) * Number(limit)
    const [jobs, total] = await Promise.all([
      Job.find(filter)
        .sort(sortMap[sort] ?? sortMap.newest)
        .skip(skip)
        .limit(Number(limit))
        .populate('employer', 'name companyName companyLogo'),
      Job.countDocuments(filter),
    ])

    res.json({ jobs, total, page: Number(page), pages: Math.ceil(total / Number(limit)) })
  } catch (err) {
    res.status(500).json({ message: err.message })
  }
})

// GET /api/jobs/featured
router.get('/featured', async (req, res) => {
  try {
    const jobs = await Job.find({ status: 'active', featured: true })
      .sort({ createdAt: -1 })
      .limit(6)
      .populate('employer', 'name companyName companyLogo')
    res.json({ jobs })
  } catch (err) {
    res.status(500).json({ message: err.message })
  }
})

// GET /api/jobs/:id
router.get('/:id', async (req, res) => {
  try {
    const job = await Job.findById(req.params.id).populate('employer', 'name companyName companyLogo companyWebsite companyDescription industry companySize')
    if (!job) return res.status(404).json({ message: 'Job not found' })
    await Job.findByIdAndUpdate(req.params.id, { $inc: { views: 1 } })
    res.json({ job })
  } catch (err) {
    res.status(500).json({ message: err.message })
  }
})

// POST /api/jobs — employer only
router.post(
  '/',
  protect,
  requireRole('employer'),
  [
    body('title').trim().notEmpty().withMessage('Title required'),
    body('description').trim().notEmpty().withMessage('Description required'),
    body('location').trim().notEmpty().withMessage('Location required'),
    body('type').isIn(['full-time', 'part-time', 'contract', 'internship', 'freelance']).withMessage('Invalid type'),
    body('category').trim().notEmpty().withMessage('Category required'),
    body('experienceLevel').isIn(['entry', 'mid', 'senior', 'lead', 'executive']).withMessage('Invalid experience level'),
  ],
  validate,
  async (req, res) => {
    try {
      const job = await Job.create({
        ...req.body,
        employer: req.user._id,
        companyName: req.user.companyName || req.user.name,
        companyLogo: req.user.companyLogo,
      })
      res.status(201).json({ job })
    } catch (err) {
      res.status(500).json({ message: err.message })
    }
  },
)

// PUT /api/jobs/:id — employer owner only
router.put('/:id', protect, requireRole('employer'), async (req, res) => {
  try {
    const job = await Job.findById(req.params.id)
    if (!job) return res.status(404).json({ message: 'Job not found' })
    if (job.employer.toString() !== req.user._id.toString()) {
      return res.status(403).json({ message: 'Not your job' })
    }
    const allowed = [
      'title', 'description', 'requirements', 'responsibilities', 'location',
      'remote', 'type', 'category', 'salaryMin', 'salaryMax', 'salaryCurrency',
      'salaryPeriod', 'skills', 'experienceLevel', 'applicationDeadline', 'status', 'featured',
    ]
    for (const key of allowed) {
      if (req.body[key] !== undefined) job[key] = req.body[key]
    }
    await job.save()
    res.json({ job })
  } catch (err) {
    res.status(500).json({ message: err.message })
  }
})

// DELETE /api/jobs/:id — employer owner only
router.delete('/:id', protect, requireRole('employer'), async (req, res) => {
  try {
    const job = await Job.findById(req.params.id)
    if (!job) return res.status(404).json({ message: 'Job not found' })
    if (job.employer.toString() !== req.user._id.toString()) {
      return res.status(403).json({ message: 'Not your job' })
    }
    await job.deleteOne()
    res.json({ message: 'Job deleted' })
  } catch (err) {
    res.status(500).json({ message: err.message })
  }
})

// GET /api/jobs/employer/mine — employer's own jobs
router.get('/employer/mine', protect, requireRole('employer'), async (req, res) => {
  try {
    const jobs = await Job.find({ employer: req.user._id }).sort({ createdAt: -1 })
    res.json({ jobs })
  } catch (err) {
    res.status(500).json({ message: err.message })
  }
})

export default router

