import { Router } from 'express'
import Application from '../models/Application.js'
import Job from '../models/Job.js'
import { protect, requireRole } from '../middleware/auth.js'
import { uploadResume } from '../middleware/upload.js'
import {
  sendApplicationConfirmation,
  sendNewApplicationAlert,
  sendStatusUpdate,
} from '../utils/email.js'

const router = Router()

// POST /api/applications — candidate applies
router.post('/', protect, requireRole('candidate'), (req, res) => {
  uploadResume(req, res, async (err) => {
    if (err) return res.status(400).json({ message: err.message })
    try {
      const { jobId, coverLetter } = req.body
      if (!req.file) return res.status(400).json({ message: 'Resume is required' })

      const job = await Job.findById(jobId).populate('employer', 'name email')
      if (!job) return res.status(404).json({ message: 'Job not found' })
      if (job.status !== 'active') return res.status(400).json({ message: 'Job is no longer active' })

      const existing = await Application.findOne({ job: jobId, candidate: req.user._id })
      if (existing) return res.status(400).json({ message: 'Already applied to this job' })

      const resumeUrl = `/uploads/${req.file.filename}`
      const application = await Application.create({
        job: jobId,
        candidate: req.user._id,
        employer: job.employer._id,
        coverLetter,
        resumeUrl,
      })

      await Job.findByIdAndUpdate(jobId, { $inc: { applicationCount: 1 } })

      // Send emails (non-blocking)
      Promise.all([
        sendApplicationConfirmation({
          candidateEmail: req.user.email,
          candidateName: req.user.name,
          jobTitle: job.title,
          companyName: job.companyName,
        }),
        sendNewApplicationAlert({
          employerEmail: job.employer.email,
          employerName: job.employer.name,
          candidateName: req.user.name,
          jobTitle: job.title,
          applicationId: application._id,
        }),
      ]).catch(console.error)

      res.status(201).json({ application })
    } catch (err) {
      if (err.code === 11000) return res.status(400).json({ message: 'Already applied to this job' })
      res.status(500).json({ message: err.message })
    }
  })
})

// GET /api/applications/mine — candidate's own applications
router.get('/mine', protect, requireRole('candidate'), async (req, res) => {
  try {
    const applications = await Application.find({ candidate: req.user._id })
      .populate('job', 'title companyName location type status')
      .sort({ createdAt: -1 })
    res.json({ applications })
  } catch (err) {
    res.status(500).json({ message: err.message })
  }
})

// GET /api/applications/job/:jobId — employer sees apps for a job
router.get('/job/:jobId', protect, requireRole('employer'), async (req, res) => {
  try {
    const job = await Job.findById(req.params.jobId)
    if (!job) return res.status(404).json({ message: 'Job not found' })
    if (job.employer.toString() !== req.user._id.toString()) {
      return res.status(403).json({ message: 'Not your job' })
    }
    const applications = await Application.find({ job: req.params.jobId })
      .populate('candidate', 'name email headline skills location resumeUrl')
      .sort({ createdAt: -1 })
    res.json({ applications })
  } catch (err) {
    res.status(500).json({ message: err.message })
  }
})

// GET /api/applications/employer — all apps for employer's jobs
router.get('/employer', protect, requireRole('employer'), async (req, res) => {
  try {
    const applications = await Application.find({ employer: req.user._id })
      .populate('job', 'title companyName location type')
      .populate('candidate', 'name email headline skills')
      .sort({ createdAt: -1 })
    res.json({ applications })
  } catch (err) {
    res.status(500).json({ message: err.message })
  }
})

// PATCH /api/applications/:id/status — employer updates status
router.patch('/:id/status', protect, requireRole('employer'), async (req, res) => {
  try {
    const { status } = req.body
    const validStatuses = ['reviewing', 'shortlisted', 'rejected', 'hired']
    if (!validStatuses.includes(status)) {
      return res.status(400).json({ message: 'Invalid status' })
    }

    const application = await Application.findById(req.params.id)
      .populate('candidate', 'name email')
      .populate('job', 'title')

    if (!application) return res.status(404).json({ message: 'Application not found' })
    if (application.employer.toString() !== req.user._id.toString()) {
      return res.status(403).json({ message: 'Not authorized' })
    }

    application.status = status
    await application.save()

    sendStatusUpdate({
      candidateEmail: application.candidate.email,
      candidateName: application.candidate.name,
      jobTitle: application.job.title,
      status,
    }).catch(console.error)

    res.json({ application })
  } catch (err) {
    res.status(500).json({ message: err.message })
  }
})

export default router

